mapper.select:
SELECT callback_id FROM sys_im_callback_event WHERE tenant_id = #{tenantId} AND callback_id = #{callbackId}
  AND config_id = #{configId} AND task_mapping_id = #{todoMappingId} AND action_type = #{action}
  AND status = 'PROCESSING' AND claim_until = #{claimUntil} AND claim_until > NOW() FOR UPDATE

SELECT mapping_id FROM sys_im_todo_mapping WHERE tenant_id = #{tenantId} AND mapping_id = #{todoMappingId}
  AND config_id = #{configId} AND task_id = #{taskId} AND assignment_version = #{assignmentVersion}
  AND receiver_user_id = #{userId} AND version = #{todoVersion} FOR SHARE

SELECT menu.menu_id FROM sys_user_role user_role
JOIN sys_role role_row ON role_row.role_id = user_role.role_id AND role_row.tenant_id = #{tenantId}
JOIN sys_role_menu role_menu ON role_menu.role_id = role_row.role_id AND role_menu.tenant_id = #{tenantId}
JOIN sys_menu menu ON menu.menu_id = role_menu.menu_id
WHERE user_role.tenant_id = #{tenantId} AND user_role.user_id = #{userId}
FOR SHARE

SELECT menu_id FROM sys_menu WHERE menu_id IN
#{menuId}
FOR SHARE
